CONFIG_SHA = '255d819017e61982e94f02aa7f1e17ce557f4a6f6015fe7003a1d173e166688d'
APPROVED_LIVE_IDLE_SHA = '0e9b31ca5cc387bfb60200d8a676b720d16b052645945c75892661838388d19f'
APPROVED_HELPER_PINS = {'contract.py': '2be138163b815665bd2e0c1dfe37db4d5bbf6c954f8af60b7e9d7fe7370456e8', 'prelaunch_stop.py': 'e7975c01de8561a99dbbbf8e4870717c0624485e7f6f23287ca48a71745e4e9e', 'live_idle.py': '0e9b31ca5cc387bfb60200d8a676b720d16b052645945c75892661838388d19f'}
HELPER_ORDER = ('contract.py', 'prelaunch_stop.py', 'live_idle.py')
PC_ROOT = Path('/opt/dgx-v4/hx/mimo-registry-r16')

def load_helpers(read, need, sha):
    need(type(APPROVED_HELPER_PINS) is dict and set(APPROVED_HELPER_PINS) == set(HELPER_ORDER) and (APPROVED_HELPER_PINS['live_idle.py'] == APPROVED_LIVE_IDLE_SHA), 'exact_readonly_helper_closure')
    originals = {}
    for name in HELPER_ORDER:
        raw, st = read(PC_ROOT / 'service' / name, limit=2097152)
        need(sha(raw) == APPROVED_HELPER_PINS[name] and st[3:7] == [0, 989, 33056, 1], 'exact_readonly_helper_source')
        originals[name] = (raw, st)
    absent = object()
    saved = {n[:-3]: sys.modules.get(n[:-3], absent) for n in HELPER_ORDER}
    mods = {}
    try:
        for name in HELPER_ORDER:
            key = name[:-3]
            m = types.ModuleType(key)
            m.__file__ = str(PC_ROOT / 'service' / name)
            sys.modules[key] = m
            mods[key] = m
            exec(compile(originals[name][0], m.__file__, 'exec'), m.__dict__)
    finally:
        for key, value in saved.items():
            if value is absent:
                sys.modules.pop(key, None)
            else:
                sys.modules[key] = value
    return (mods['live_idle'], originals)

def main():
    if APPROVED_RELEASE is None or SOURCE_PINS is None or CONFIG_SHA is None or (APPROVED_LIVE_IDLE_SHA is None):
        raise RuntimeError('current_idle_producer_pending')
    if os.getuid() != 999 or os.geteuid() != 999 or sys.platform != 'linux':
        raise RuntimeError('fixed_UID999_readonly')
    sys.path.insert(0, '/opt/dgx-v4/hx/runtime')
    from B_OWNER_RECOVERY_R25_WIRING.common import need, protected_read, sha, strict, encode
    for path, pin in SOURCE_PINS.items():
        need(sha(Path(path).read_bytes()) == pin, 'actual_source118_before_fixed_channel')
    m, originals = load_helpers(protected_read, need, sha)
    from node_adapter.client import load_config, SshTransport
    cfg = load_config('/etc/dgx-home-ai/node-adapter.json')
    need(sha(Path('/etc/dgx-home-ai/node-adapter.json').read_bytes()) == CONFIG_SHA, 'unchanged_actual_channel_config')
    channel = types.SimpleNamespace(config=cfg, _transport=SshTransport(cfg), _clock=time.time)
    need(len(sys.argv) == 3 and sys.argv[1] == '--generation' and sys.argv[2].isdigit() and (int(sys.argv[2]) > 0), 'actual_Root_collected_Core_generation_only')
    result = {n: m.exchange_current_idle(channel, n, int(sys.argv[2])) for n in m.NODES}
    for name, original in originals.items():
        need(protected_read(PC_ROOT / 'service' / name, limit=2097152) == original, 'readonly_helper_after_actual_exchange')
    for path, pin in SOURCE_PINS.items():
        need(sha(Path(path).read_bytes()) == pin, 'actual_source118_after_fixed_channel')
    sys.stdout.buffer.write(encode(result))
    return 0
if __name__ == '__main__':
    raise SystemExit(main())
